INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-05-31-austria-ebinterface-70', '2026-05-31', '2026-05', 'AUSTRIAPRO is developing ebInterface 7.0, due in Q4 2026, adding a formal syntax binding to the European e-invoicing standard EN 16931 — no mandatory migration from 6.0/6.1 has been announced.', '<h3>🇦🇹 Austria''s ebInterface standard prepares its next update</h3>
<p>AUSTRIAPRO — the e-billing working group of the WKO, Austria''s Federal Economic Chamber, which has developed and maintained ebInterface since 2009 — is preparing version 7.0 of the standard, with release planned for the fourth quarter of 2026. The central technical change is a formal syntax binding to the European e-invoicing standard EN 16931, building on the semantic alignment that ebInterface has carried since version 5.0.</p>
<p>The current version, 6.1, has been available since 25 August 2022 and remains fully valid; Austrian federal agencies continue to accept versions 4.3, 5.0, 6.0, and 6.1 for B2G submissions. No mandatory migration to 7.0 has been announced, and AUSTRIAPRO has stated that development is proceeding with backward compatibility in mind — businesses and software providers currently on 6.0 or 6.1 do not need to migrate immediately once 7.0 ships.</p>
<p>For companies planning or extending their Austria support, the tighter EN 16931 binding is nonetheless a relevant development: it simplifies implementation and increases confidence in long-term interoperability with the rest of the EU, even though ebInterface itself remains a distinctly Austrian standard rather than a European one.</p>', 'https://www.wko.at/netzwerke/was-ist-ebinterface', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-05-31-austria-ebinterface-70', id FROM countries WHERE name_en = 'Austria';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-31-austria-ebinterface-70', 'en', 'Austria''s ebInterface standard prepares its next update', 'AUSTRIAPRO is developing ebInterface 7.0, due in Q4 2026, adding a formal syntax binding to the European e-invoicing standard EN 16931 — no mandatory migration from 6.0/6.1 has been announced.', '<h3>🇦🇹 Austria''s ebInterface standard prepares its next update</h3>
<p>AUSTRIAPRO — the e-billing working group of the WKO, Austria''s Federal Economic Chamber, which has developed and maintained ebInterface since 2009 — is preparing version 7.0 of the standard, with release planned for the fourth quarter of 2026. The central technical change is a formal syntax binding to the European e-invoicing standard EN 16931, building on the semantic alignment that ebInterface has carried since version 5.0.</p>
<p>The current version, 6.1, has been available since 25 August 2022 and remains fully valid; Austrian federal agencies continue to accept versions 4.3, 5.0, 6.0, and 6.1 for B2G submissions. No mandatory migration to 7.0 has been announced, and AUSTRIAPRO has stated that development is proceeding with backward compatibility in mind — businesses and software providers currently on 6.0 or 6.1 do not need to migrate immediately once 7.0 ships.</p>
<p>For companies planning or extending their Austria support, the tighter EN 16931 binding is nonetheless a relevant development: it simplifies implementation and increases confidence in long-term interoperability with the rest of the EU, even though ebInterface itself remains a distinctly Austrian standard rather than a European one.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-31-austria-ebinterface-70', 'es', 'El estándar ebInterface de Austria prepara su próxima actualización', 'AUSTRIAPRO está desarrollando ebInterface 7.0, previsto para el cuarto trimestre de 2026, que añade una vinculación formal de sintaxis con la norma europea de facturación electrónica EN 16931 — no se ha anunciado ninguna migración obligatoria desde 6.0/6.1.', '<h3>🇦🇹 El estándar ebInterface de Austria prepara su próxima actualización</h3>
<p>AUSTRIAPRO — el grupo de trabajo de facturación electrónica de la WKO, la Cámara Federal de Economía de Austria, que ha desarrollado y mantenido ebInterface desde 2009 — está preparando la versión 7.0 del estándar, con lanzamiento previsto para el cuarto trimestre de 2026. El cambio técnico central es una vinculación formal de sintaxis con la norma europea de facturación electrónica EN 16931, sobre la base de la alineación semántica que ebInterface mantiene desde la versión 5.0.</p>
<p>La versión actual, 6.1, está disponible desde el 25 de agosto de 2022 y sigue siendo totalmente válida; los organismos federales austriacos continúan aceptando las versiones 4.3, 5.0, 6.0 y 6.1 para las presentaciones B2G. No se ha anunciado ninguna migración obligatoria a la 7.0, y AUSTRIAPRO ha declarado que el desarrollo avanza teniendo en cuenta la compatibilidad con versiones anteriores — las empresas y proveedores de software que actualmente usan 6.0 o 6.1 no necesitan migrar de inmediato una vez que se lance la 7.0.</p>
<p>Para las empresas que planean o amplían su soporte para Austria, la vinculación más estrecha con EN 16931 sigue siendo un desarrollo relevante: simplifica la implementación y aumenta la confianza en la interoperabilidad a largo plazo con el resto de la UE, aunque ebInterface en sí sigue siendo un estándar claramente austriaco y no europeo.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-31-austria-ebinterface-70', 'de', 'Österreichs ebInterface-Standard bereitet das nächste Update vor', 'AUSTRIAPRO entwickelt ebInterface 7.0, das für das vierte Quartal 2026 geplant ist und eine formale Syntaxbindung an die europäische E-Rechnungs-Norm EN 16931 hinzufügt — ein verpflichtender Umstieg von 6.0/6.1 wurde nicht angekündigt.', '<h3>🇦🇹 Österreichs ebInterface-Standard bereitet das nächste Update vor</h3>
<p>AUSTRIAPRO — der E-Billing-Arbeitskreis der WKO, der österreichischen Wirtschaftskammer, die ebInterface seit 2009 entwickelt und pflegt — bereitet Version 7.0 des Standards vor, deren Veröffentlichung für das vierte Quartal 2026 geplant ist. Die zentrale technische Änderung ist eine formale Syntaxbindung an die europäische E-Rechnungs-Norm EN 16931, aufbauend auf der semantischen Angleichung, die ebInterface seit Version 5.0 trägt.</p>
<p>Die aktuelle Version 6.1 ist seit dem 25. August 2022 verfügbar und bleibt vollständig gültig; österreichische Bundesbehörden akzeptieren für B2G-Einreichungen weiterhin die Versionen 4.3, 5.0, 6.0 und 6.1. Ein verpflichtender Umstieg auf 7.0 wurde nicht angekündigt, und AUSTRIAPRO hat erklärt, dass die Entwicklung unter Berücksichtigung der Abwärtskompatibilität erfolgt — Unternehmen und Softwareanbieter, die derzeit 6.0 oder 6.1 nutzen, müssen nach Erscheinen von 7.0 nicht sofort umsteigen.</p>
<p>Für Unternehmen, die ihre Österreich-Unterstützung planen oder erweitern, ist die engere EN-16931-Bindung dennoch eine relevante Entwicklung: Sie vereinfacht die Umsetzung und erhöht das Vertrauen in die langfristige Interoperabilität mit dem Rest der EU, auch wenn ebInterface selbst ein ausgesprochen österreichischer Standard bleibt und kein europäischer.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-31-austria-ebinterface-70', 'fr', 'La norme ebInterface autrichienne prépare sa prochaine mise à jour', 'AUSTRIAPRO développe ebInterface 7.0, attendue au quatrième trimestre 2026, ajoutant une liaison syntaxique formelle à la norme européenne de facturation électronique EN 16931 — aucune migration obligatoire depuis la 6.0/6.1 n''a été annoncée.', '<h3>🇦🇹 La norme ebInterface autrichienne prépare sa prochaine mise à jour</h3>
<p>AUSTRIAPRO — le groupe de travail e-facturation de la WKO, la Chambre économique fédérale autrichienne, qui développe et maintient ebInterface depuis 2009 — prépare la version 7.0 de la norme, dont la publication est prévue au quatrième trimestre 2026. Le changement technique central est une liaison syntaxique formelle à la norme européenne de facturation électronique EN 16931, s''appuyant sur l''alignement sémantique qu''ebInterface porte depuis la version 5.0.</p>
<p>La version actuelle, 6.1, est disponible depuis le 25 août 2022 et reste pleinement valide ; les organismes fédéraux autrichiens continuent d''accepter les versions 4.3, 5.0, 6.0 et 6.1 pour les soumissions B2G. Aucune migration obligatoire vers la 7.0 n''a été annoncée, et AUSTRIAPRO a indiqué que le développement se poursuit dans un souci de rétrocompatibilité — les entreprises et éditeurs de logiciels actuellement en 6.0 ou 6.1 n''ont pas besoin de migrer immédiatement une fois la 7.0 publiée.</p>
<p>Pour les entreprises qui planifient ou étendent leur prise en charge de l''Autriche, la liaison plus stricte à l''EN 16931 reste néanmoins un développement pertinent : elle simplifie la mise en œuvre et renforce la confiance dans l''interopérabilité à long terme avec le reste de l''UE, même si ebInterface demeure une norme spécifiquement autrichienne plutôt qu''européenne.</p>');

